import { gsap } from 'gsap';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, Color } = ctx.THREE;

  // ---------- Config extraction ----------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';

  // ---------- Core group ----------
  const root = new Group();

  // ---------- Constants ----------
  const CARD_W = 1.5;
  const CARD_H = 1.9;
  const GAP = 0.25;
  const START_X = -((3 * CARD_W + 2 * GAP) / 2) + CARD_W / 2; // center row at origin

  // ---------- Load card texture ----------
  const texturePromise = ctx.textureLoader.loadTexture(imageUrl);

  // ---------- Helpers ----------
  const makeGradientMaterial = () => {
    const mat = new MeshStandardNodeMaterial({
      transparent: true,
      roughness: 0.6,
      metalness: 0.25,
      clearcoat: 0.15,
    });
    // vertical gradient #191921 → #121218
    const grad = mix(
      color('#191921'),
      color('#121218'),
      uv().y
    );
    mat.colorNode = grad;
    return mat;
  };

  const makeBorderMaterial = () => {
    const mat = new MeshBasicNodeMaterial({ color: '#26262f' });
    mat.transparent = true;
    mat.opacity = 1;
    return mat;
  };

  const makeDiscMaterial = () => {
    const mat = new MeshStandardNodeMaterial({
      color: '#26262f',
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2,
      emissive: new Color('#ff2a38'),
      emissiveIntensity: 1.6,
    });
    return mat;
  };

  // ---------- Create Cards ----------
  const timelines = [];
  const cardGroups = [];

  for (let i = 0; i < 3; i++) {
    const cardGroup = new Group();
    cardGroup.position.x = START_X + i * (CARD_W + GAP);
    root.add(cardGroup);
    cardGroups.push(cardGroup);

    // Border plane (slightly larger)
    const borderGeom = new PlaneGeometry(CARD_W + 0.012, CARD_H + 0.012);
    const borderMat = makeBorderMaterial();
    const borderMesh = new Mesh(borderGeom, borderMat);
    borderMesh.position.z = -0.002;
    cardGroup.add(borderMesh);

    // Card background plane
    const cardGeom = new PlaneGeometry(CARD_W, CARD_H);
    const cardMat = makeGradientMaterial();
    cardMat.transparent = true;
    cardMat.opacity = 0; // start invisible for fade‑up
    const cardMesh = new Mesh(cardGeom, cardMat);
    cardGroup.add(cardMesh);

    // Icon disc
    const discGeom = new CylinderGeometry(0.2, 0.2, 0.05, 32);
    const discMat = makeDiscMaterial();
    const discMesh = new Mesh(discGeom, discMat);
    // Position disc near top, respecting interior padding (0.375)
    const PAD = 0.375;
    const iconY = CARD_H / 2 - PAD - 0.025; // half disc height offset
    discMesh.position.set(0, iconY, 0.02);
    cardGroup.add(discMesh);

    // Text items (glyph, title, body)
    const baseIdx = i * 3;
    const glyphItem = items[baseIdx];
    const titleItem = items[baseIdx + 1];
    const bodyItem = items[baseIdx + 2];

    // Glyph text
    if (glyphItem) {
      const glyph = ctx.fontAtlas.createText(glyphItem.text ?? '', {
        fontSize: 20,
        color: '#ff2a38',
        align: 'center',
      });
      glyph.position.set(0, iconY + 0.02, 0.04);
      cardGroup.add(glyph);
    }

    // Title text
    if (titleItem) {
      const title = ctx.fontAtlas.createText(titleItem.text ?? '', {
        fontSize: 20,
        color: '#e8ecf2',
        align: 'center',
      });
      const titleY = iconY - 0.3;
      title.position.set(0, titleY, 0.04);
      cardGroup.add(title);
    }

    // Body text
    if (bodyItem) {
      const body = ctx.fontAtlas.createText(bodyItem.text ?? '', {
        fontSize: 13,
        color: '#e8ecf2',
        align: 'center',
        maxWidthPx: 400,
      });
      const bodyY = iconY - 0.5;
      body.position.set(0, bodyY, 0.04);
      cardGroup.add(body);
    }

    // ---------- Hover lift timeline ----------
    const hoverTl = gsap.timeline({ paused: true });
    hoverTl
      .to(
        cardGroup.position,
        {
          y: '+=0.06',
          duration: 0.18,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        },
        0
      )
      .to(
        discMat,
        {
          emissiveIntensity: 2.2,
          duration: 0.18,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        },
        0
      );

    // Store for cleanup
    timelines.push(hoverTl);

    // Attach handlers
    cardGroup.userData.handlers = {
      hoverIn: () => hoverTl.play(),
      hoverOut: () => hoverTl.reverse(),
    };
  }

  // ---------- Stagger‑cards entrance ----------
  const entranceTl = gsap.timeline();
  cardGroups.forEach((cg, idx) => {
    // start slightly lower and invisible
    cg.position.y -= 0.2;
    const cardMesh = cg.children.find((c) => c.isMesh && c.material && c.material.opacity !== undefined);
    if (cardMesh) {
      cardMesh.material.opacity = 0;
    }
    entranceTl
      .to(
        cg.position,
        {
          y: '+=0.2',
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        },
        idx * 0.08
      )
      .to(
        cardMesh?.material ?? {},
        {
          opacity: 1,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        },
        idx * 0.08
      );
  });
  timelines.push(entranceTl);

  // ---------- Texture application ----------
  texturePromise.then((tex) => {
    cardGroups.forEach((cg) => {
      const cardMesh = cg.children.find(
        (c) => c.isMesh && c.geometry && c.geometry.type === 'PlaneGeometry'
      );
      if (cardMesh) {
        cardMesh.material.map = tex;
        cardMesh.material.needsUpdate = true;
      }
    });
  });

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
  };

  return root;
}
